problems.solution:
def gd_step(w, dL, lr):
    return w - lr * dL(w)

def newton_step(w, dL, d2L):
    return w - dL(w) / d2L(w)

def run(step, w0, steps):
    w = w0
    for _ in range(steps):
        w = step(w)
    return w
